package com.yuegang.zhihui.inventory.api;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.common.web.TraceIdResolver;import com.yuegang.zhihui.inventory.application.InventoryMaintenanceService;import com.yuegang.zhihui.inventory.security.InventoryInternalSecurity;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/internal/v1/inventory/maintenance")public final class InventoryMaintenanceController{private final InventoryMaintenanceService service;private final InventoryInternalSecurity security;public InventoryMaintenanceController(InventoryMaintenanceService s,InventoryInternalSecurity x){service=s;security=x;}@PostMapping("/release-expired")ApiResponse<Map<String,Integer>>release(HttpServletRequest r){security.verify(r);return ApiResponse.success(Map.of("released",service.releaseExpired()),TraceIdResolver.resolve(r));}@PostMapping("/reconcile")ApiResponse<List<InventoryReconciliationView>>reconcile(HttpServletRequest r){security.verify(r);return ApiResponse.success(service.reconcile(),TraceIdResolver.resolve(r));}}
